#!/bin/sh
# Compatibility for operator environments through Dagsverk 2.x. Never print values.
dagsverk_alias() {
  if [ "$2" = x ]; then
    if [ "$4" = x ] && [ "$3" != "$5" ]; then
      printf '%s overrides deprecated TIMEKEEPER_%s; values are redacted.\n' "$1" "${1#DAGSVERK_}" >&2
    fi
  elif [ "$4" = x ]; then
    export "$1=$5"
  fi
}
